                best_vector = vector
                best_versions = {
                    name: row['version'] for name, row in selected.items()
                }
            return

        name = unresolved[0]
        for row in packages.get(name, []):
            if name in roots and not in_root_range(row['version'], roots[name]):
                continue
            next_selected = dict(selected)
            next_selected[name] = row
            next_required = set(required)
            next_required.update(dependencies(row))
            search(next_required, next_selected)

    search(set(roots), {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
